CREATE TABLE coupon_template(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL,threshold_fen BIGINT NOT NULL,discount_fen BIGINT NOT NULL,total INT NOT NULL,issued INT NOT NULL DEFAULT 0,valid_from DATETIME(6) NOT NULL,valid_until DATETIME(6) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),CHECK(threshold_fen>=0),CHECK(discount_fen>0),CHECK(issued>=0 AND issued<=total)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE member_coupon(id BIGINT PRIMARY KEY AUTO_INCREMENT,member_id BIGINT NOT NULL,template_id BIGINT NOT NULL,name VARCHAR(100) NOT NULL,threshold_fen BIGINT NOT NULL,discount_fen BIGINT NOT NULL,valid_from DATETIME(6) NOT NULL,valid_until DATETIME(6) NOT NULL,status VARCHAR(32) NOT NULL,order_no VARCHAR(64) NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),UNIQUE(template_id,member_id),UNIQUE(order_no),FOREIGN KEY(template_id) REFERENCES coupon_template(id),INDEX idx_coupon_member(member_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE coupon_log(id BIGINT PRIMARY KEY AUTO_INCREMENT,coupon_id BIGINT NOT NULL,order_no VARCHAR(64) NOT NULL,action VARCHAR(32) NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),UNIQUE(coupon_id,order_no,action),FOREIGN KEY(coupon_id) REFERENCES member_coupon(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
